// 1. 可靠投递 - 本地消息表
@Service
public class ReliableMessageService {
    @Transactional
    public void sendMessage(String topic, Object payload) {
        // 1. 业务操作
        doBusiness();

        // 2. 写本地消息表（同一事务）
        LocalMessage msg = new LocalMessage();
        msg.setMessageId(UUID.randomUUID().toString());
        msg.setTopic(topic);
        msg.setPayload(JSON.toJSONString(payload));
        msg.setStatus("PENDING");
        localMessageRepo.save(msg);
    }
}

// 后台任务发送
@Scheduled(fixedDelay = 1000)
public void pollAndSend() {
    List<LocalMessage> msgs = localMessageRepo
        .findByStatus("PENDING", 100);
    for (LocalMessage msg : msgs) {
        try {
            SendResult result = rocketMQTemplate
                .syncSend(msg.getTopic(), msg.getPayload());
            if (result.getSendStatus() == SendStatus.SEND_OK) {
                msg.setStatus("SENT");
                localMessageRepo.update(msg);
            }
        } catch (Exception e) {
            msg.setRetryCount(msg.getRetryCount() + 1);
            localMessageRepo.update(msg);
        }
    }
}

// 2. 幂等消费
@Component
public class IdempotentConsumer {
    @Autowired
    private ProcessedMessageRepo processedRepo;

    @RocketMQListener(topic = "order-topic")
    public void handleMessage(OrderMessage msg) {
        // 去重检查
        if (processedRepo.exists(msg.getMessageId())) {
            log.info("消息已处理，跳过: {}", msg.getMessageId());
            return;
        }

        try {
            // 处理消息
            processOrder(msg);
            // 标记已处理
            processedRepo.save(new ProcessedMessage(msg.getMessageId()));
        } catch (Exception e) {
            // 消费失败，抛异常触发重试
            throw new RuntimeException("消费失败", e);
        }
    }
}

// 3. 顺序消息 - 按订单ID分区
public void sendOrderly(String orderId, OrderEvent event) {
    rocketMQTemplate.syncSendOrderly(
        "order-topic",
        JSON.toJSONString(event),
        orderId  // 分区key
    );
}

// 4. 延迟消息 - 订单超时取消
public void sendDelayMessage(String orderId, int delayLevel) {
    Message<String> message = MessageBuilder
        .withPayload(orderId)
        .build();
    rocketMQTemplate.syncSend("order-timeout-topic",
        message, 3000, delayLevel);  // delayLevel=3 表示10s
}
